using Autodesk.AutoCAD.Runtime;using System.Windows.Forms;using AcApp=Autodesk.AutoCAD.ApplicationServices.Application;
[assembly:ExtensionApplication(typeof(LSE.AutoCADElectrical.ProjectEnvironment.Plugin))][assembly:CommandClass(typeof(LSE.AutoCADElectrical.ProjectEnvironment.Commands))]
namespace LSE.AutoCADElectrical.ProjectEnvironment;
public sealed class Plugin:IExtensionApplication{public void Initialize(){}public void Terminate(){}}
public sealed class Commands{
 [CommandMethod("LSEENV",CommandFlags.Modal)]public void Env(){try{var s=SettingsService.Load();string active=AcadeBridgeService.TryGetActiveProject(s);string start=active.Length>0?active:AcadeBridgeService.GuessProjectNearActiveDrawing();string? reload;bool retag;using(var f=new EnvironmentForm(start,active)){AcApp.ShowModalDialog(f);reload=f.ReloadProjectPath;retag=f.RetagRequested;}After(reload,retag);}catch(System.Exception ex){ErrorService.Show(null,"LSEENV",ex);}}
 [CommandMethod("LSEENVWIRES",CommandFlags.Modal)]public void Wires(){try{var s=SettingsService.Load();string active=AcadeBridgeService.TryGetActiveProject(s);string start=active.Length>0?active:AcadeBridgeService.GuessProjectNearActiveDrawing();string? reload;bool retag;using(var f=new WireSchemeForm(start,active)){AcApp.ShowModalDialog(f);reload=f.ReloadProjectPath;retag=f.RetagRequested;}After(reload,retag);}catch(System.Exception ex){ErrorService.Show(null,"LSEENVWIRES",ex);}}
 [CommandMethod("LSEENVPROFILES",CommandFlags.Modal)]public void Profiles(){try{var s=SettingsService.Load();string active=AcadeBridgeService.TryGetActiveProject(s);using var f=new ProfilesForm(active.Length>0?active:AcadeBridgeService.GuessProjectNearActiveDrawing());AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSEENVPROFILES",ex);}}
 [CommandMethod("LSEENVSNAPSHOT",CommandFlags.Modal)]public void Snapshot(){try{var s=SettingsService.Load();string active=AcadeBridgeService.TryGetActiveProject(s);using var f=new SnapshotForm(active.Length>0?active:AcadeBridgeService.GuessProjectNearActiveDrawing());AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSEENVSNAPSHOT",ex);}}
 [CommandMethod("LSEENVSETTINGS",CommandFlags.Modal)]public void Settings(){try{using var f=new EnvSettingsForm();AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSEENVSETTINGS",ex);}}
 [CommandMethod("LSEENVDIAG",CommandFlags.Modal)]public void Diag(){try{using var f=new TextReportForm("LSE_Env Diagnostics",DiagnosticsService.BuildReport());AcApp.ShowModalDialog(f);}catch(System.Exception ex){ErrorService.Show(null,"LSEENVDIAG",ex);}}
 static void After(string? reload,bool retag){var s=SettingsService.Load();if(reload is not null)AcadeBridgeService.ReloadProject(reload,s);if(retag)AcadeBridgeService.QueueRetag(s);}
}
